insert into detective_cases(id, slug, title, title_ar, description, description_ar, case_type, difficulty, age_min, age_max, status, created_by, category, estimated_minutes, briefing, briefing_ar, objective, objective_ar, cover_image_path) values ('80f455ff-9ca9-5a6e-962d-89cf99391c32', $q$the-clock-that-stopped$q$, $q$The Clock That Stopped at 8:17$q$, $q$سر الساعة التي توقفت عند ٨:١٧$q$, $q$The great astronomical clock in a small museum stopped at 8:17 the evening before a school visit. Some people suspect tampering, but the clock, its service tools, and three different time records may tell a more careful story.$q$, $q$توقفت الساعة الفلكية الكبيرة في متحف صغير عند ٨:١٧ مساءً قبل زيارة مدرسية. ظن بعضهم أن أحدًا عبث بها، لكن الساعة وأدوات صيانتها وثلاثة سجلات زمنية قد تكشف تفسيرًا أدق.$q$, 'FULL', 2, 10, 16, 'DRAFT', v_user, $q$المنطق والتسلسل الزمني$q$, 18, $q$At 8:31 p.m. by the corridor clock, caretaker Omar reported that the museum's astronomical clock had stopped. The hands were motionless, but their position alone did not explain why. The backup-power monitor showed no interruption. Clock conservator Lina had a scheduled maintenance visit, while guide Sami says he saw the clock running earlier. Inspect the gallery, workshop, and corridor records. Decide what is directly observed, what the evidence supports, and whether there is enough evidence to call this sabotage.$q$, $q$عند ٨:٣١ مساءً بحسب ساعة الممر، أبلغ الحارس عمر أن الساعة الفلكية توقفت. كانت عقاربها ساكنة، لكن موضعها وحده لا يفسر سبب التوقف. ولم يُظهر سجل الطاقة الاحتياطية أي انقطاع. كان لدى مرمّمة الساعات لينا موعد صيانة، ويقول المرشد سامي إنه رأى الساعة تعمل قبل ذلك. افحص القاعة والورشة وسجلات الممر، ثم ميّز بين ما تراه مباشرة وما تدعمه الأدلة، وهل يكفي ذلك لاتهام أحد بالتخريب.$q$, $q$Use independent records to distinguish scheduled maintenance from a mechanical failure or sabotage, while avoiding conclusions that go beyond the evidence.$q$, $q$استخدم سجلات مستقلة للتمييز بين الصيانة المجدولة والعطل الميكانيكي أو التخريب، وتجنب الاستنتاجات التي تتجاوز ما تثبته الأدلة.$q$, 'demo/detective/clock-that-stopped/cover.webp') on conflict (id) do nothing;
insert into detective_case_versions(id, case_id, version_number, status, created_by) values ('145fa7cf-0419-5c44-b1b2-5a07804ebfd9', '80f455ff-9ca9-5a6e-962d-89cf99391c32', 1, 'DRAFT', v_user) on conflict (id) do nothing;
insert into detective_stages(id, version_id, stage_key, position, title, title_ar, unlock_rule) values ('d2dcceee-5ef8-5628-a28c-80382da7b877', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', $q$observe$q$, 1, $q$Inspect the Clock Gallery$q$, $q$افحص قاعة الساعة$q$, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_stages(id, version_id, stage_key, position, title, title_ar, unlock_rule) values ('4d32321c-763f-5f29-a3ae-e9b6e38f0d5f', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', $q$records$q$, 2, $q$Check the Service Records$q$, $q$راجع سجلات الصيانة$q$, $q${"requires_stage":"observe"}$q$::jsonb) on conflict (id) do nothing;
insert into detective_stages(id, version_id, stage_key, position, title, title_ar, unlock_rule) values ('ec4c8308-4278-5b85-a3f5-22eb4f6a7010', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', $q$conclude$q$, 3, $q$Explain What Happened$q$, $q$فسّر ما حدث$q$, $q${"requires_stage":"records"}$q$::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('2d968875-2f28-5403-850a-b82129760982', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 1, $q$The Clock Gallery$q$, $q$قاعة الساعة$q$, 'demo/detective/clock-that-stopped/scene-1.webp', $q$The astronomical clock is intact. Its hands are motionless just after eight, and the pendulum is still behind the lower glass panel. Look closely at the small brass part beside the pendulum before deciding why it stopped.$q$, $q$الساعة الفلكية سليمة من الخارج. عقاربها ساكنة بعد الثامنة بقليل، والبندول متوقف خلف اللوح الزجاجي السفلي. تفحّص القطعة النحاسية الصغيرة بجوار البندول قبل أن تقرر سبب التوقف.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('deec805f-3372-5638-8860-d2f0c628aa28', '2d968875-2f28-5403-850a-b82129760982', $q$clock_hands$q$, $q$The paused clock face$q$, $q$The paused clock face$q$, $q$واجهة الساعة المتوقفة$q$, 42, 34, 15, 27, $q$The hands are visibly motionless just after eight. The exact scheduled stop time, 8:17 p.m., is stated on the separate maintenance card; the dial illustration should not be used to infer exact minutes.$q$, $q$العقارب ساكنة بوضوح بعد الثامنة بقليل. أما وقت الإيقاف المجدول بدقة، ٨:١٧ مساءً، فيرد في بطاقة الصيانة المنفصلة؛ ولا ينبغي استنتاج الدقائق الدقيقة من رسم الواجهة.$q$, $q$الملاحظة المباشرة هي سكون العقارب. ويُعرف وقت ٨:١٧ من بطاقة الصيانة لا من محاولة قراءة رسم توضيحي بدقة.$q$, $q$الملاحظة المباشرة هي سكون العقارب. ويُعرف وقت ٨:١٧ من بطاقة الصيانة لا من محاولة قراءة رسم توضيحي بدقة.$q$, $q$FACT$q$, 3, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('cc3e19a4-ba79-5b7a-9528-7060c2d486a5', '2d968875-2f28-5403-850a-b82129760982', $q$service_pin$q$, $q$The brass service pin$q$, $q$The brass service pin$q$, $q$مسمار وضع الصيانة النحاسي$q$, 43, 63, 13, 8, $q$A small brass service pin is engaged beside the pendulum. In this clock, the pin holds the mechanism safely still during scheduled service.$q$, $q$يوجد مسمار نحاسي صغير في موضع الصيانة بجوار البندول. في هذه الساعة يثبّت المسمار الآلية بأمان أثناء الصيانة المجدولة.$q$, $q$يدل وضع المسمار على وضع الصيانة، لكن ربطه بموعد مصرح به يحتاج إلى مقارنته بأمر الصيانة وسجل الدخول.$q$, $q$يدل وضع المسمار على وضع الصيانة، لكن ربطه بموعد مصرح به يحتاج إلى مقارنته بأمر الصيانة وسجل الدخول.$q$, $q$OBSERVATION$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('a027d3f7-ffec-5222-a751-d3f935c2e9b5', '2d968875-2f28-5403-850a-b82129760982', $q$intact_mechanism$q$, $q$No visible damage$q$, $q$No visible damage$q$, $q$لا تلف ظاهر في الآلية$q$, 44, 71, 12, 13, $q$The glass and visible gear housing are unbroken, with no bent parts or scattered pieces in the gallery.$q$, $q$الزجاج وغطاء التروس الظاهر غير مكسورين، ولا توجد أجزاء منحنية أو متناثرة في القاعة.$q$, $q$يضعف ذلك فرضية الكسر الواضح، لكنه لا يبرهن بمفرده أن عطلًا داخليًا مستحيل.$q$, $q$يضعف ذلك فرضية الكسر الواضح، لكنه لا يبرهن بمفرده أن عطلًا داخليًا مستحيل.$q$, $q$FACT$q$, 3, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('c50ad01e-99d8-583e-9b4b-5f0f118bfc14', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 2, $q$The Restoration Workshop$q$, $q$ورشة الترميم$q$, 'demo/detective/clock-that-stopped/scene-2.webp', $q$The orderly workshop contains a signed service card, the correct brass tool, and an oily cleaning cloth. Separate routine traces from evidence of wrongdoing.$q$, $q$تضم الورشة المرتبة بطاقة صيانة موقعة وأداة نحاسية مناسبة وقطعة قماش عليها أثر زيت. ميّز بين آثار العمل المعتادة والدليل على ارتكاب مخالفة.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('9df4464b-2e04-5115-a663-96ad47ac0d8e', 'c50ad01e-99d8-583e-9b4b-5f0f118bfc14', $q$service_order$q$, $q$The approved maintenance card$q$, $q$The approved maintenance card$q$, $q$بطاقة الصيانة المعتمدة$q$, 9, 23, 21, 41, $q$The dated work card schedules a safe service stop at 8:17 p.m. and bears clock conservator Lina's initials. The card was approved before the evening visit.$q$, $q$تحدد بطاقة العمل المؤرخة إيقافًا آمنًا للصيانة عند ٨:١٧ مساءً، وتحمل أحرف اسم مرمّمة الساعات لينا. اعتُمدت البطاقة قبل زيارة المساء.$q$, $q$تدعم أن الإيقاف كان مخططًا ومصرحًا به. لا تُقرأ كتوقيع اعتراف بارتكاب تخريب.$q$, $q$تدعم أن الإيقاف كان مخططًا ومصرحًا به. لا تُقرأ كتوقيع اعتراف بارتكاب تخريب.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('d4c263dc-92ac-52af-8686-efc345cfb488', 'c50ad01e-99d8-583e-9b4b-5f0f118bfc14', $q$clock_service_key$q$, $q$The proper service key$q$, $q$The proper service key$q$, $q$مفتاح الصيانة المناسب$q$, 25, 59, 19, 21, $q$A clean precision key and the small brass service pin lie beside an open, undamaged gear case. They are the normal tools listed on the service card.$q$, $q$يوجد مفتاح دقيق نظيف ومسمار الصيانة النحاسي بجوار غطاء تروس مفتوح بلا تلف. وهما الأداتان المعتادتان المذكورتان في بطاقة الصيانة.$q$, $q$تتوافق الأدوات مع الإجراء المكتوب، ولا تظهر عليها قرينة على كسر أو اقتحام.$q$, $q$تتوافق الأدوات مع الإجراء المكتوب، ولا تظهر عليها قرينة على كسر أو اقتحام.$q$, $q$OBSERVATION$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('6d5ab0d8-a9ec-55cf-bb8c-83a58cf13b0a', 'c50ad01e-99d8-583e-9b4b-5f0f118bfc14', $q$oily_gloves$q$, $q$Oil on the work cloth and gloves$q$, $q$Oil on the work cloth and gloves$q$, $q$زيت على القماش والقفازات$q$, 71, 51, 25, 38, $q$A faint clock-oil mark is visible on the cloth and ordinary conservator gloves. Oil is used for routine clock servicing and is not unique to any person.$q$, $q$تظهر بقعة خفيفة من زيت الساعات على القماش والقفازات العادية المستخدمة في الترميم. يُستخدم الزيت في الصيانة المعتادة ولا يخص شخصًا بعينه.$q$, $q$قرينة سياقية ضعيفة؛ تتفق مع الصيانة ولا تكفي لاتهام أي مشتبه به.$q$, $q$قرينة سياقية ضعيفة؛ تتفق مع الصيانة ولا تكفي لاتهام أي مشتبه به.$q$, $q$OBSERVATION$q$, 2, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('b9df9fd6-3697-51f7-b014-ea5070ddc14d', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 3, $q$The Service Corridor$q$, $q$ممر الخدمة$q$, 'demo/detective/clock-that-stopped/scene-3.webp', $q$The corridor has a signed access ledger, a steady backup-power monitor, and a digital clock reading 8:31. A calibration entry in the open ledger says the corridor clock runs fourteen minutes fast. Compare these records before building the timeline.$q$, $q$في الممر سجل دخول مفتوح وشاشة طاقة احتياطية مستقرة وساعة رقمية تشير إلى ٨:٣١. يذكر سجل المعايرة في الدفتر المفتوح أن ساعة الممر تتقدم أربع عشرة دقيقة. قارن السجلات قبل بناء التسلسل الزمني.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('97e78d75-f70f-526f-8afa-078f068c283d', 'b9df9fd6-3697-51f7-b014-ea5070ddc14d', $q$access_log$q$, $q$Lina's signed access record$q$, $q$Lina's signed access record$q$, $q$سجل دخول لينا الموقّع$q$, 0, 64, 35, 30, $q$The access ledger records Lina entering the gallery corridor at 8:05 p.m. and leaving at 8:26 p.m. A calibration entry in the same ledger says the nearby corridor clock runs fourteen minutes fast.$q$, $q$يسجل دفتر الدخول دخول لينا إلى ممر القاعة عند ٨:٠٥ مساءً وخروجها عند ٨:٢٦. ويذكر سجل معايرة في الدفتر نفسه أن ساعة الممر القريبة تتقدم أربع عشرة دقيقة.$q$, $q$يجمع بين وجود لينا في المكان والموعد المكتوب، لكنه لا يثبت مخالفة لأن بطاقة العمل معتمدة.$q$, $q$يجمع بين وجود لينا في المكان والموعد المكتوب، لكنه لا يثبت مخالفة لأن بطاقة العمل معتمدة.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('4060364b-6041-5e27-bc96-0a986043df14', 'b9df9fd6-3697-51f7-b014-ea5070ddc14d', $q$power_monitor$q$, $q$No recorded power interruption$q$, $q$No recorded power interruption$q$, $q$لا انقطاع مسجل للطاقة$q$, 70, 39, 8, 15, $q$The backup monitor shows continuous power through the evening interval. The astronomical clock is mechanically driven, but the record also contradicts the reported building-wide flicker.$q$, $q$تُظهر شاشة الطاقة الاحتياطية استمرار التغذية خلال فترة المساء. تعمل الساعة الفلكية بآلية ميكانيكية، كما يناقض السجل رواية انطفاء كهرباء المبنى كلها.$q$, $q$يضعف فرضية أن انقطاع الكهرباء أوقف الساعة، ويناقض ادعاء انطفاء الإنارة الشامل، لكنه لا يحدد وحده من أوقف الآلية.$q$, $q$يضعف فرضية أن انقطاع الكهرباء أوقف الساعة، ويناقض ادعاء انطفاء الإنارة الشامل، لكنه لا يحدد وحده من أوقف الآلية.$q$, $q$FACT$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('6b794a27-db7d-5c09-8e53-ca942f0a17ef', 'b9df9fd6-3697-51f7-b014-ea5070ddc14d', $q$fast_corridor_clock$q$, $q$The corridor clock reads 8:31$q$, $q$The corridor clock reads 8:31$q$, $q$ساعة الممر تشير إلى ٨:٣١$q$, 48, 12, 14, 11, $q$The digital wall clock visibly displays 8:31. Compare it with the calibration entry in the access ledger, which says the corridor clock runs fourteen minutes fast; its corrected time is about 8:17.$q$, $q$تعرض الساعة الرقمية على الحائط ٨:٣١. قارنها بسجل المعايرة في دفتر الدخول الذي يذكر أنها تتقدم أربع عشرة دقيقة؛ فيكون وقتها المصحح نحو ٨:١٧.$q$, $q$يشرح طرح ١٤ دقيقة من قراءة ساعة الممر وصولها إلى نحو ٨:١٧، وهو وقت بطاقة الصيانة. لا يثبت ذلك وحده من أوقف الساعة.$q$, $q$يشرح طرح ١٤ دقيقة من قراءة ساعة الممر وصولها إلى نحو ٨:١٧، وهو وقت بطاقة الصيانة. لا يثبت ذلك وحده من أوقف الساعة.$q$, $q$FACT$q$, 3, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('53d751b4-ec74-591c-9729-b3f3077c53fa', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', '9df4464b-2e04-5115-a663-96ad47ac0d8e', 'cc3e19a4-ba79-5b7a-9528-7060c2d486a5', $q$SUPPORTS$q$, $q$The approved 8:17 service instruction matches the engaged service-mode pin.$q$, $q$يتوافق موعد الصيانة المعتمد عند ٨:١٧ مع مسمار وضع الصيانة المثبت.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('52608397-a9f6-56e5-ba7a-546fd1082592', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', '9df4464b-2e04-5115-a663-96ad47ac0d8e', '97e78d75-f70f-526f-8afa-078f068c283d', $q$SUPPORTS$q$, $q$The scheduled service window overlaps Lina's signed access window.$q$, $q$يتداخل موعد الصيانة المجدول مع فترة دخول لينا الموقعة.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('5d8f8f49-d3b7-5c8d-bcc5-4f68b488327f', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', '6b794a27-db7d-5c09-8e53-ca942f0a17ef', 'deec805f-3372-5638-8860-d2f0c628aa28', $q$TEMPORAL$q$, $q$Correcting the corridor clock by fourteen minutes gives about 8:17, matching the service-card time; the illustration itself is not the precise time source.$q$, $q$يؤدي تصحيح ساعة الممر بطرح ١٤ دقيقة إلى نحو ٨:١٧، وهو ما يطابق بطاقة الصيانة؛ أما الرسم نفسه فليس مصدرًا دقيقًا للوقت.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('884367f0-64df-5174-8cde-a1815198cee0', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', '6d5ab0d8-a9ec-55cf-bb8c-83a58cf13b0a', '9df4464b-2e04-5115-a663-96ad47ac0d8e', $q$CONTEXTUAL$q$, $q$Clock oil is consistent with ordinary maintenance and is not proof of sabotage or identity.$q$, $q$يتفق زيت الساعات مع الصيانة العادية ولا يثبت التخريب أو هوية الفاعل.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('d9e631d3-b0d3-55c0-b1bf-0ce06e08ba15', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 'a027d3f7-ffec-5222-a751-d3f935c2e9b5', 'cc3e19a4-ba79-5b7a-9528-7060c2d486a5', $q$SUPPORTS$q$, $q$The undamaged visible mechanism and the safe service pin fit a routine service stop better than forced damage.$q$, $q$تنسجم الآلية الظاهرة السليمة ومسمار الصيانة الآمن مع إيقاف روتيني أكثر من الإتلاف بالقوة.$q$) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('19f69ea0-1fec-50ab-b775-899e0eab5fc6', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 'd2dcceee-5ef8-5628-a28c-80382da7b877', $q$MULTIPLE_CHOICE$q$, $q$Which details can you directly observe in the gallery image?$q$, $q$ما التفاصيل التي يمكنك ملاحظتها مباشرة في صورة القاعة؟$q$, $q$[{"id":"a","text":"The clock hands are still and the pendulum is motionless","text_ar":"عقارب الساعة ساكنة والبندول لا يتحرك"},{"id":"b","text":"Lina sabotaged the clock","text_ar":"خرّبت لينا الساعة"},{"id":"c","text":"The clock stopped because the building lost power","text_ar":"توقفت الساعة بسبب انقطاع كهرباء المبنى"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$الملاحظة المباشرة هي سكون العقارب. ويُعرف وقت ٨:١٧ من بطاقة الصيانة لا من محاولة قراءة رسم توضيحي بدقة.$q$, $q$الملاحظة المباشرة هي سكون العقارب. ويُعرف وقت ٨:١٧ من بطاقة الصيانة لا من محاولة قراءة رسم توضيحي بدقة.$q$, array['deec805f-3372-5638-8860-d2f0c628aa28'::uuid,'cc3e19a4-ba79-5b7a-9528-7060c2d486a5'::uuid]::uuid[], 8, -2, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('d5877af8-bb0f-515e-967b-de63710cf0ce', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 'd2dcceee-5ef8-5628-a28c-80382da7b877', $q$TRUE_FALSE$q$, $q$The fact that the clock hands are stopped proves that someone sabotaged the clock.$q$, $q$يثبت توقف عقارب الساعة أن شخصًا ما خرّبها.$q$, $q$[]$q$::jsonb, $q${"value":"false"}$q$::jsonb, '[]'::jsonb, $q$الملاحظة المباشرة هي سكون العقارب. ويُعرف وقت ٨:١٧ من بطاقة الصيانة لا من محاولة قراءة رسم توضيحي بدقة.$q$, $q$الملاحظة المباشرة هي سكون العقارب. ويُعرف وقت ٨:١٧ من بطاقة الصيانة لا من محاولة قراءة رسم توضيحي بدقة.$q$, array['deec805f-3372-5638-8860-d2f0c628aa28'::uuid,'cc3e19a4-ba79-5b7a-9528-7060c2d486a5'::uuid]::uuid[], 8, -2, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('da77bd8a-59cf-58fc-9346-dc5ccd0067e3', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 'd2dcceee-5ef8-5628-a28c-80382da7b877', $q$MULTIPLE_CHOICE$q$, $q$Select the clue that shows the clock was placed in its safe service mode.$q$, $q$حدّد الدليل الذي يوضح أن الساعة وُضعت في وضع الصيانة الآمن.$q$, $q$[{"id":"a","text":"The paused clock face","text_ar":"واجهة الساعة المتوقفة"},{"id":"b","text":"The brass service pin","text_ar":"مسمار وضع الصيانة النحاسي"},{"id":"c","text":"No visible damage","text_ar":"لا تلف ظاهر في الآلية"}]$q$::jsonb, $q${"option_id":"b"}$q$::jsonb, '[]'::jsonb, $q$يدل وضع المسمار على وضع الصيانة، لكن ربطه بموعد مصرح به يحتاج إلى مقارنته بأمر الصيانة وسجل الدخول.$q$, $q$يدل وضع المسمار على وضع الصيانة، لكن ربطه بموعد مصرح به يحتاج إلى مقارنته بأمر الصيانة وسجل الدخول.$q$, array['cc3e19a4-ba79-5b7a-9528-7060c2d486a5'::uuid]::uuid[], 10, -3, 3) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('2ab2edde-768e-5a78-9e1f-10d759ff44a5', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', '4d32321c-763f-5f29-a3ae-e9b6e38f0d5f', $q$MULTIPLE_CHOICE$q$, $q$Which record most directly shows that stopping the clock at 8:17 was planned and approved?$q$, $q$أي سجل يوضح مباشرة أن إيقاف الساعة عند ٨:١٧ كان مخططًا ومعتمدًا؟$q$, $q$[{"id":"a","text":"The signed maintenance card","text_ar":"بطاقة الصيانة الموقعة"},{"id":"b","text":"The oily gloves","text_ar":"القفازات التي عليها زيت"},{"id":"c","text":"The corridor clock alone","text_ar":"ساعة الممر وحدها"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$تدعم أن الإيقاف كان مخططًا ومصرحًا به. لا تُقرأ كتوقيع اعتراف بارتكاب تخريب.$q$, $q$تدعم أن الإيقاف كان مخططًا ومصرحًا به. لا تُقرأ كتوقيع اعتراف بارتكاب تخريب.$q$, array['9df4464b-2e04-5115-a663-96ad47ac0d8e'::uuid,'97e78d75-f70f-526f-8afa-078f068c283d'::uuid]::uuid[], 12, -3, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('2c093f95-caae-5e83-ab7f-30fc4304196f', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', '4d32321c-763f-5f29-a3ae-e9b6e38f0d5f', $q$MULTIPLE_CHOICE$q$, $q$What best challenges Omar's claim of a building-wide power interruption?$q$, $q$ما الدليل الأقوى على عدم صحة قول عمر بانقطاع كهرباء المبنى كله؟$q$, $q$[{"id":"a","text":"The backup monitor records continuous power","text_ar":"سجل شاشة الطاقة استمرار التغذية"},{"id":"b","text":"The clock face is brass","text_ar":"واجهة الساعة نحاسية"},{"id":"c","text":"Sami left before 8:15","text_ar":"غادر سامي قبل ٨:١٥"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$يضعف فرضية أن انقطاع الكهرباء أوقف الساعة، ويناقض ادعاء انطفاء الإنارة الشامل، لكنه لا يحدد وحده من أوقف الآلية.$q$, $q$يضعف فرضية أن انقطاع الكهرباء أوقف الساعة، ويناقض ادعاء انطفاء الإنارة الشامل، لكنه لا يحدد وحده من أوقف الآلية.$q$, array['4060364b-6041-5e27-bc96-0a986043df14'::uuid]::uuid[], 12, -3, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('e66911f0-7a46-55e4-af9e-579989107ce1', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', '4d32321c-763f-5f29-a3ae-e9b6e38f0d5f', $q$MULTIPLE_CHOICE$q$, $q$The corridor clock reads 8:31 and runs fourteen minutes fast. What is its approximate corrected time?$q$, $q$تشير ساعة الممر إلى ٨:٣١ وتتقدم ١٤ دقيقة. فما وقتها المصحح تقريبًا؟$q$, $q$[{"id":"a","text":"About 8:17","text_ar":"نحو ٨:١٧"},{"id":"b","text":"About 8:45","text_ar":"نحو ٨:٤٥"},{"id":"c","text":"The display cannot be corrected","text_ar":"لا يمكن تصحيح القراءة"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$يشرح طرح ١٤ دقيقة من قراءة ساعة الممر وصولها إلى نحو ٨:١٧، وهو وقت بطاقة الصيانة. لا يثبت ذلك وحده من أوقف الساعة.$q$, $q$يشرح طرح ١٤ دقيقة من قراءة ساعة الممر وصولها إلى نحو ٨:١٧، وهو وقت بطاقة الصيانة. لا يثبت ذلك وحده من أوقف الساعة.$q$, array['6b794a27-db7d-5c09-8e53-ca942f0a17ef'::uuid,'deec805f-3372-5638-8860-d2f0c628aa28'::uuid]::uuid[], 10, -2, 3) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('c2836130-6a6d-542e-89d9-d4c77e9e25f7', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 'ec4c8308-4278-5b85-a3f5-22eb4f6a7010', $q$MULTIPLE_CHOICE$q$, $q$Put the supported events in chronological order. Choose the correct order.$q$, $q$رتّب الأحداث التي تدعمها السجلات زمنيًا. اختر الترتيب الصحيح.$q$, $q$[{"id":"a","text":"The service card is approved → Lina enters the gallery corridor → The clock is safely stopped for service at 8:17 → Lina exits the corridor","text_ar":"اعتماد بطاقة الصيانة ← دخول لينا ممر القاعة ← إيقاف الساعة بأمان للصيانة عند ٨:١٧ ← خروج لينا من الممر"},{"id":"b","text":"Lina enters the gallery corridor → The service card is approved → The clock is safely stopped for service at 8:17 → Lina exits the corridor","text_ar":"دخول لينا ممر القاعة ← اعتماد بطاقة الصيانة ← إيقاف الساعة بأمان للصيانة عند ٨:١٧ ← خروج لينا من الممر"},{"id":"c","text":"Lina enters the gallery corridor → The clock is safely stopped for service at 8:17 → Lina exits the corridor → The service card is approved","text_ar":"دخول لينا ممر القاعة ← إيقاف الساعة بأمان للصيانة عند ٨:١٧ ← خروج لينا من الممر ← اعتماد بطاقة الصيانة"},{"id":"d","text":"Lina exits the corridor → The clock is safely stopped for service at 8:17 → Lina enters the gallery corridor → The service card is approved","text_ar":"خروج لينا من الممر ← إيقاف الساعة بأمان للصيانة عند ٨:١٧ ← دخول لينا ممر القاعة ← اعتماد بطاقة الصيانة"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$تدعم أن الإيقاف كان مخططًا ومصرحًا به. لا تُقرأ كتوقيع اعتراف بارتكاب تخريب.$q$, $q$تدعم أن الإيقاف كان مخططًا ومصرحًا به. لا تُقرأ كتوقيع اعتراف بارتكاب تخريب.$q$, array['9df4464b-2e04-5115-a663-96ad47ac0d8e'::uuid,'97e78d75-f70f-526f-8afa-078f068c283d'::uuid,'cc3e19a4-ba79-5b7a-9528-7060c2d486a5'::uuid]::uuid[], 15, -4, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('cd3cf035-970c-5625-a516-b7ee69a67d06', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 'ec4c8308-4278-5b85-a3f5-22eb4f6a7010', $q$MULTIPLE_CHOICE$q$, $q$Which explanation is not supported by the collected evidence?$q$, $q$أي تفسير لا تدعمه الأدلة التي جُمعت؟$q$, $q$[{"id":"a","text":"The clock was stopped in the approved maintenance window","text_ar":"أُوقفت الساعة ضمن موعد الصيانة المعتمد"},{"id":"b","text":"The evidence proves Lina intended to damage the clock","text_ar":"تثبت الأدلة أن لينا قصدت إتلاف الساعة"},{"id":"c","text":"The corridor clock's fast reading explains the apparent time difference","text_ar":"يفسر تقدم ساعة الممر اختلاف التوقيت الظاهري"}]$q$::jsonb, $q${"option_id":"b"}$q$::jsonb, '[]'::jsonb, $q$تدعم أن الإيقاف كان مخططًا ومصرحًا به. لا تُقرأ كتوقيع اعتراف بارتكاب تخريب.$q$, $q$تدعم أن الإيقاف كان مخططًا ومصرحًا به. لا تُقرأ كتوقيع اعتراف بارتكاب تخريب.$q$, array['9df4464b-2e04-5115-a663-96ad47ac0d8e'::uuid,'cc3e19a4-ba79-5b7a-9528-7060c2d486a5'::uuid,'6b794a27-db7d-5c09-8e53-ca942f0a17ef'::uuid]::uuid[], 15, -4, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('24901aa4-a97e-5b81-a5ad-d9044d9d2fea', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 'ec4c8308-4278-5b85-a3f5-22eb4f6a7010', $q$FINAL_CONCLUSION$q$, $q$What is the best evidence-based conclusion?$q$, $q$ما أفضل استنتاج يستند إلى الأدلة؟$q$, $q$[{"id":"a","text":"Lina performed the approved safe service stop; the evidence does not support sabotage","text_ar":"نفذت لينا إيقاف الصيانة الآمن المعتمد؛ ولا تدعم الأدلة فرضية التخريب"},{"id":"b","text":"Omar sabotaged the clock because he reported it","text_ar":"خرّب عمر الساعة لأنه أبلغ عن توقفها"},{"id":"c","text":"Sami must have stopped it because he saw it earlier","text_ar":"لا بد أن سامي أوقفها لأنه رآها تعمل قبل ذلك"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$The best-supported explanation is that clock conservator Lina stopped the astronomical clock at 8:17 as part of an approved, safe maintenance procedure. The signed service card schedules that exact stop, the service pin is engaged, and Lina's access record covers the maintenance window. The corridor clock's 8:31 reading is corrected to about 8:17 because that clock runs fourteen minutes fast. The backup monitor records no power interruption. The evidence supports routine maintenance, not sabotage; there is no basis to accuse Lina of wrongdoing.$q$, $q$أفضل تفسير تدعمه الأدلة هو أن مرمّمة الساعات لينا أوقفت الساعة الفلكية عند ٨:١٧ ضمن إجراء صيانة آمن ومعتمد. تحدد بطاقة الصيانة الموقعة هذا الموعد، ومسمار الصيانة مثبت، ويغطي سجل دخول لينا فترة العمل. تُصحح قراءة ساعة الممر ٨:٣١ إلى نحو ٨:١٧ لأنها تتقدم أربع عشرة دقيقة. كما لا يسجل جهاز الطاقة أي انقطاع. تدعم الأدلة صيانة روتينية لا تخريبًا، ولا يوجد أساس لاتهام لينا بارتكاب مخالفة.$q$, array['9df4464b-2e04-5115-a663-96ad47ac0d8e'::uuid,'cc3e19a4-ba79-5b7a-9528-7060c2d486a5'::uuid,'97e78d75-f70f-526f-8afa-078f068c283d'::uuid,'4060364b-6041-5e27-bc96-0a986043df14'::uuid,'6b794a27-db7d-5c09-8e53-ca942f0a17ef'::uuid]::uuid[], 20, -5, 3) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('34fc0e26-fc7b-5edc-99c2-303e5b62af5b', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', $q$Lina Haddad$q$, $q$لينا حداد$q$, $q$Maintains the museum's mechanical clocks and had the correct service key.$q$, $q$تتولى صيانة ساعات المتحف الميكانيكية، ولديها مفتاح الصيانة المناسب. أُدرجت لها زيارة صيانة أسبوعية معتمدة قبل موعد الزيارة المدرسية.$q$, $q$مرمّمة الساعات$q$, $q$Clock conservator$q$, $q${"18:00":"Approved service card issued","20:05":"Gallery corridor entry recorded","20:17":"Scheduled safe service stop","20:26":"Exit recorded"}$q$::jsonb, $q$قالت إنها أوقفت الآلية عند ٨:١٧ وفق بطاقة العمل ثم غادرت بعد إتمام الفحص.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('0f11c88f-0a17-5c69-bcfe-470057ad22a3', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', $q$Omar Nasser$q$, $q$عمر ناصر$q$, $q$Checks the galleries and reports building issues during the evening shift.$q$, $q$يتفقد القاعات ويبلغ عن أعطال المبنى خلال نوبة المساء. أبلغ عن توقف الساعة وقال إنه لاحظ وميضًا في الإنارة قرب وقت البلاغ.$q$, $q$حارس المساء$q$, $q$Night caretaker$q$, $q${"20:31":"Corridor clock reading noted","20:34":"Report filed using the fast corridor clock"}$q$::jsonb, $q$قال إنه رأى ساعة الممر عند ٨:٣١ وظن أن توقف الساعة وقع في ذلك الوقت.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('f6e5ae71-a4f2-5a4a-ae11-fd9717779efe', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', $q$Sami Farouk$q$, $q$سامي فاروق$q$, $q$Led the last school-group walkthrough and left before the service window.$q$, $q$قاد آخر جولة للطلاب وغادر قبل فترة الصيانة. كان آخر من تحدث عن رؤيته للساعة تعمل، لكنه غادر قبل الموعد المحدد لإيقافها.$q$, $q$مرشد المتحف$q$, $q$Museum guide$q$, $q${"20:12":"Last gallery walkthrough","20:15":"Exit recorded"}$q$::jsonb, $q$قال إنه رأى البندول يتحرك عند مروره بالقاعة قبل الثامنة والربع.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('a4868b75-e5f3-52e3-958e-eeac1d192fba', '34fc0e26-fc7b-5edc-99c2-303e5b62af5b', $q$I stopped the clock at 8:17 as the approved service card instructed, then checked that the mechanism was safely held.$q$, $q$أوقفت الساعة عند ٨:١٧ كما طلبت بطاقة الصيانة المعتمدة، ثم تحققت من تثبيت الآلية بأمان.$q$, $q$TRUE$q$, array['9df4464b-2e04-5115-a663-96ad47ac0d8e'::uuid,'cc3e19a4-ba79-5b7a-9528-7060c2d486a5'::uuid,'97e78d75-f70f-526f-8afa-078f068c283d'::uuid]::uuid[], $q$تتفق أقوال لينا مع بطاقة العمل وسجل وجودها ووضع الصيانة. الأدلة تدعم عملًا مجدولًا لا تخريبًا.$q$, $q$تتفق أقوال لينا مع بطاقة العمل وسجل وجودها ووضع الصيانة. الأدلة تدعم عملًا مجدولًا لا تخريبًا.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('3d40652c-0864-5b5e-9450-af4dd5cdcfa3', '0f11c88f-0a17-5c69-bcfe-470057ad22a3', $q$The whole corridor lost power, and the clock stopped at 8:31.$q$, $q$انقطعت الكهرباء عن الممر كله، وتوقفت الساعة عند ٨:٣١.$q$, $q$FALSE$q$, array['4060364b-6041-5e27-bc96-0a986043df14'::uuid,'6b794a27-db7d-5c09-8e53-ca942f0a17ef'::uuid,'deec805f-3372-5638-8860-d2f0c628aa28'::uuid]::uuid[], $q$لا يسجل جهاز الطاقة انقطاعًا، وساعة الممر تتقدم ١٤ دقيقة؛ كما أن موضع عقارب الساعة الفلكية لا يثبت وحده وقت توقف الآلية.$q$, $q$لا يسجل جهاز الطاقة انقطاعًا، وساعة الممر تتقدم ١٤ دقيقة؛ كما أن موضع عقارب الساعة الفلكية لا يثبت وحده وقت توقف الآلية.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('b662be55-686d-5e49-bb7a-cf69011b2712', 'f6e5ae71-a4f2-5a4a-ae11-fd9717779efe', $q$I saw the pendulum moving shortly before 8:15, then left the museum.$q$, $q$رأيت البندول يتحرك قبل ٨:١٥ بقليل، ثم غادرت المتحف.$q$, $q$TRUE$q$, array['97e78d75-f70f-526f-8afa-078f068c283d'::uuid,'9df4464b-2e04-5115-a663-96ad47ac0d8e'::uuid]::uuid[], $q$يتوافق قوله مع سجل مغادرته قبل نافذة الصيانة، ولا يثبت أنه لمس الساعة أو عرف توقيت إيقافها.$q$, $q$يتوافق قوله مع سجل مغادرته قبل نافذة الصيانة، ولا يثبت أنه لمس الساعة أو عرف توقيت إيقافها.$q$) on conflict (id) do nothing;
