insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('f4de817f-f65b-5eb9-b3d4-6a41cff03ce1', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', $q$omar_corridor_reading$q$, $q$Omar notes 8:31 on a clock that is fourteen minutes fast$q$, $q$يسجل عمر ٨:٣١ على ساعة تتقدم ١٤ دقيقة$q$, $q$20:31$q$, 6) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('0431fb83-1051-553e-a0b2-8a1d81662c31', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 'd2dcceee-5ef8-5628-a28c-80382da7b877', $q$Separate what the clock shows from what you think caused it to stop.$q$, $q$افصل بين ما تعرضه الساعة وبين تفسيرك لسبب توقفها.$q$, '{}'::jsonb, -1, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('a7ee9b40-43d0-5bd8-b4b4-4b0d4a90e884', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', '4d32321c-763f-5f29-a3ae-e9b6e38f0d5f', $q$Compare the approved service card with the access log; then check the power record independently.$q$, $q$قارن بطاقة الصيانة المعتمدة بسجل الدخول، ثم افحص سجل الطاقة على نحو مستقل.$q$, '{}'::jsonb, -2, 2) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('0aec0042-bf9a-5631-85c8-c23e28c536f7', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', 'ec4c8308-4278-5b85-a3f5-22eb4f6a7010', $q$The strongest conclusion explains the service pin, the signed schedule, and the fast corridor clock without assuming criminal intent.$q$, $q$أفضل استنتاج يفسر مسمار الصيانة والموعد الموقع وساعة الممر المتقدمة من دون افتراض نية إجرامية.$q$, '{}'::jsonb, -3, 3) on conflict (id) do nothing;
insert into detective_solutions(id, version_id, public_reveal, public_reveal_ar, solution_key, alternative_hypotheses, educational_explanation, educational_explanation_ar) values ('fe90aca3-bdad-500e-bc5b-cb51044e0211', '145fa7cf-0419-5c44-b1b2-5a07804ebfd9', $q$The best-supported explanation is that clock conservator Lina stopped the astronomical clock at 8:17 as part of an approved, safe maintenance procedure. The signed service card schedules that exact stop, the service pin is engaged, and Lina's access record covers the maintenance window. The corridor clock's 8:31 reading is corrected to about 8:17 because that clock runs fourteen minutes fast. The backup monitor records no power interruption. The evidence supports routine maintenance, not sabotage; there is no basis to accuse Lina of wrongdoing.$q$, $q$أفضل تفسير تدعمه الأدلة هو أن مرمّمة الساعات لينا أوقفت الساعة الفلكية عند ٨:١٧ ضمن إجراء صيانة آمن ومعتمد. تحدد بطاقة الصيانة الموقعة هذا الموعد، ومسمار الصيانة مثبت، ويغطي سجل دخول لينا فترة العمل. تُصحح قراءة ساعة الممر ٨:٣١ إلى نحو ٨:١٧ لأنها تتقدم أربع عشرة دقيقة. كما لا يسجل جهاز الطاقة أي انقطاع. تدعم الأدلة صيانة روتينية لا تخريبًا، ولا يوجد أساس لاتهام لينا بارتكاب مخالفة.$q$, $q${"final_question":"24901aa4-a97e-5b81-a5ad-d9044d9d2fea"}$q$::jsonb, $q$[{"en":"A power outage stopped the clock.","ar":"أوقف انقطاع الكهرباء الساعة.","why_wrong_en":"The backup monitor records continuous power, and the clock is mechanically driven. The outage explanation is not supported by the records.","why_wrong_ar":"يسجل جهاز الطاقة استمرار التغذية، كما أن الساعة تعمل بآلية ميكانيكية. لا تدعم السجلات تفسير انقطاع الكهرباء."},{"en":"Lina sabotaged the clock because she had access and a service key.","ar":"خرّبت لينا الساعة لأنها تملك تصريح دخول ومفتاح صيانة.","why_wrong_en":"Access alone is not proof. The approved service card, safe service pin, and matching time support a scheduled procedure; there is no damage or evidence of harmful intent.","why_wrong_ar":"الدخول وحده ليس دليلًا. تدعم بطاقة الصيانة المعتمدة ومسمار الأمان والموعد المتطابق إجراءً مجدولًا، ولا يوجد تلف أو دليل على نية الإضرار."},{"en":"Omar stopped the clock at 8:31.","ar":"أوقف عمر الساعة عند ٨:٣١.","why_wrong_en":"The corridor clock runs fourteen minutes fast, and its displayed reading does not identify who operated the clock mechanism.","why_wrong_ar":"ساعة الممر تتقدم أربع عشرة دقيقة، وقراءتها لا تحدد من تعامل مع آلية الساعة."}]$q$::jsonb, $q$Good investigation separates observation from interpretation. The face shows that the hands are stopped; the engaged pin shows service mode; the approved card and signed access log connect that mode to scheduled work. Independent records challenge the power-outage claim and explain the corridor-clock discrepancy. The evidence supports an authorized maintenance action, not sabotage. Presence and access are not proof of guilt.$q$, $q$يفصل التحقيق الجيد بين الملاحظة والتفسير. تُظهر الواجهة أن العقارب ساكنة؛ ويُظهر المسمار وضع الصيانة؛ وتربط بطاقة العمل المعتمدة وسجل الدخول الموقع ذلك الموضع بصيانة مجدولة. تناقض السجلات المستقلة ادعاء انقطاع الطاقة وتفسر فرق التوقيت في ساعة الممر. تدعم الأدلة صيانة مصرحًا بها لا تخريبًا. الوجود وامتلاك صلاحية الدخول لا يثبتان الذنب.$q$) on conflict (id) do nothing;
